import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import base64
from io import BytesIO
from datetime import datetime

# ── Load data ──
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)

# ── Feature engineering ──
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10
df['DecadeLabel'] = df['Decade'].apply(lambda d: f"{d}s")
df['MoM_Change'] = df['Crude_Oil_Price'].diff()
df['MoM_Pct_Change'] = df['Crude_Oil_Price'].pct_change() * 100
df['YoY_Change'] = df['Crude_Oil_Price'].diff(12)
df['YoY_Pct_Change'] = df['Crude_Oil_Price'].pct_change(12) * 100
df['Rolling_12M_Std'] = df['Crude_Oil_Price'].rolling(12).std()

# ── KPIs ──
price_min = df['Crude_Oil_Price'].min()
price_max = df['Crude_Oil_Price'].max()
price_range = price_max - price_min
date_min = df['Date'].min()
date_max = df['Date'].max()
years_span = (date_max - date_min).days / 365.25
cagr = ((df['Crude_Oil_Price'].iloc[-1] / df['Crude_Oil_Price'].iloc[0]) ** (1 / years_span) - 1) * 100

max_mom_idx = df['MoM_Change'].abs().idxmax()
max_mom_abs = df.loc[max_mom_idx, 'MoM_Change']
max_mom_pct = df.loc[max_mom_idx, 'MoM_Pct_Change']
max_mom_date = df.loc[max_mom_idx, 'Date']

max_mom_pct_idx = df['MoM_Pct_Change'].abs().idxmax()
max_mom_pct_val = df.loc[max_mom_pct_idx, 'MoM_Pct_Change']
max_mom_pct_date = df.loc[max_mom_pct_idx, 'Date']

overall_std = df['Crude_Oil_Price'].std()
overall_mean = df['Crude_Oil_Price'].mean()
overall_median = df['Crude_Oil_Price'].median()
p10 = df['Crude_Oil_Price'].quantile(0.10)
p25 = df['Crude_Oil_Price'].quantile(0.25)
p75 = df['Crude_Oil_Price'].quantile(0.75)
p90 = df['Crude_Oil_Price'].quantile(0.90)

# Decade with highest average price
decade_stats = df.groupby('DecadeLabel')['Crude_Oil_Price'].agg(['mean', 'std', 'min', 'max', 'count']).reset_index()
decade_stats.columns = ['Decade', 'Mean_Price', 'Std_Dev', 'Min_Price', 'Max_Price', 'Count']
highest_decade = decade_stats.loc[decade_stats['Mean_Price'].idxmax(), 'Decade']
highest_decade_mean = decade_stats.loc[decade_stats['Mean_Price'].idxmax(), 'Mean_Price']

# ── Volatility & Shocks ──
top_mom_increases = df.nlargest(5, 'MoM_Change')[['Date', 'Crude_Oil_Price', 'MoM_Change', 'MoM_Pct_Change']]
top_mom_decreases = df.nsmallest(5, 'MoM_Change')[['Date', 'Crude_Oil_Price', 'MoM_Change', 'MoM_Pct_Change']]

# ── Chart generation helpers ──
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    b64 = base64.b64encode(buf.getvalue()).decode()
    plt.close(fig)
    return b64

# ── Chart 1: Full Time Series ──
fig1, ax1 = plt.subplots(figsize=(16, 7))
ax1.plot(df['Date'], df['Crude_Oil_Price'], color='#1a5276', linewidth=1.2, alpha=0.9)
ax1.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.12, color='#2980b9')

# Annotate key events
events = [
